#include <string>
#include <vector>
#include <algorithm>

class Solution {
    std::vector<int> z_function(const std::string& st) {
        int n = st.size();
        std::vector<int> z(n, 0);
        int l = 0, r = 0;
        for (int i = 1; i < n; ++i) {
            if (i <= r) z[i] = std::min(r - i + 1, z[i - l]);
            while (i + z[i] < n && st[z[i]] == st[i + z[i]]) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        return z;
    }
public:
    int minStartingIndex(std::string s, std::string pattern) {
        int n = s.size(), m = pattern.size();
        if (m > n) return -1;

        auto z1 = z_function(pattern + s);
        std::string rev_pat = pattern, rev_s = s;
        std::reverse(rev_pat.begin(), rev_pat.end());
        std::reverse(rev_s.begin(), rev_s.end());
        auto z2 = z_function(rev_pat + rev_s);

        for (int i = 0; i <= n - m; ++i) {
            int pref = z1[m + i];
            int suff = z2[n - i];
            if (pref + suff >= m - 1) return i;
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minStartingIndex(String s, String pattern) {
        int n = s.length(), m = pattern.length();
        if (m > n) return -1;

        int[] z1 = zFunction(pattern + s);
        String revPat = new StringBuilder(pattern).reverse().toString();
        String revS = new StringBuilder(s).reverse().toString();
        int[] z2 = zFunction(revPat + revS);

        for (int i = 0; i <= n - m; i++) {
            int pref = z1[m + i];
            int suff = z2[n - i];
            if (pref + suff >= m - 1) return i;
        }
        return -1;
    }

    private int[] zFunction(String st) {
        int len = st.length();
        int[] z = new int[len];
        int l = 0, r = 0;
        for (int i = 1; i < len; i++) {
            if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
            while (i + z[i] < len && st.charAt(z[i]) == st.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        return z;
    }
}

